import Autosize = require( './index' );


// TESTS //

// The function returns an autosize instance...
{
	new Autosize(); // $ExpectType Autosize
	new Autosize( {} ); // $ExpectType Autosize
	new Autosize( { 'type': 'fit' } ); // $ExpectType Autosize
	new Autosize( { 'contains': 'padding', 'resize': true, 'type': 'fit' } ); // $ExpectType Autosize

	Autosize(); // $ExpectType Autosize
	Autosize( {} ); // $ExpectType Autosize
	Autosize( { 'type': 'fit' } ); // $ExpectType Autosize
	Autosize( { 'contains': 'padding', 'resize': true, 'type': 'fit' } ); // $ExpectType Autosize
}

// The compiler throws an error if the function is provided an options argument which is not an object...
{
	new Autosize( '5' ); // $ExpectError
	new Autosize( 5 ); // $ExpectError
	new Autosize( true ); // $ExpectError
	new Autosize( false ); // $ExpectError
	new Autosize( null ); // $ExpectError
	new Autosize( [] ); // $ExpectError
	new Autosize( ( x: number ): number => x ); // $ExpectError

	Autosize( '5' ); // $ExpectError
	Autosize( 5 ); // $ExpectError
	Autosize( true ); // $ExpectError
	Autosize( false ); // $ExpectError
	Autosize( null ); // $ExpectError
	Autosize( [] ); // $ExpectError
	Autosize( ( x: number ): number => x ); // $ExpectError
}

// The compiler throws an error if the function is provided a `contains` option which is not a supported method...
{
	new Autosize( { 'contains': 'abc' } ); // $ExpectError
	new Autosize( { 'contains': 5 } ); // $ExpectError
	new Autosize( { 'contains': true } ); // $ExpectError
	new Autosize( { 'contains': false } ); // $ExpectError
	new Autosize( { 'contains': null } ); // $ExpectError
	new Autosize( { 'contains': [] } ); // $ExpectError
	new Autosize( { 'contains': {} } ); // $ExpectError
	new Autosize( { 'contains': ( x: number ): number => x } ); // $ExpectError
}

// The compiler throws an error if the function is provided a `resize` option which is not a boolean...
{
	new Autosize( { 'resize': '5' } ); // $ExpectError
	new Autosize( { 'resize': 5 } ); // $ExpectError
	new Autosize( { 'resize': null } ); // $ExpectError
	new Autosize( { 'resize': [] } ); // $ExpectError
	new Autosize( { 'resize': {} } ); // $ExpectError
	new Autosize( { 'resize': ( x: number ): number => x } ); // $ExpectError
}

// The compiler throws an error if the function is provided a `type` option which is not a supported method...
{
	new Autosize( { 'type': 'abc' } ); // $ExpectError
	new Autosize( { 'type': 5 } ); // $ExpectError
	new Autosize( { 'type': true } ); // $ExpectError
	new Autosize( { 'type': false } ); // $ExpectError
	new Autosize( { 'type': null } ); // $ExpectError
	new Autosize( { 'type': [] } ); // $ExpectError
	new Autosize( { 'type': {} } ); // $ExpectError
	new Autosize( { 'type': ( x: number ): number => x } ); // $ExpectError
}

// The compiler throws an error if the function is provided more than one argument...
{
	new Autosize( {}, {} ); // $ExpectError
	Autosize( {}, {} ); // $ExpectError
}

// An autosize instance has autosize properties...
{
	const autosize = new Autosize();

	const contains = autosize.contains; // $ExpectType ContainsMethod
	const resize = autosize.resize; // $ExpectType boolean
	const type = autosize.type; // $ExpectType AutosizeMethod

	if ( contains === 'padding' || resize || type === 'none' ) {
		throw new Error( 'unexpected error' );
	}
}

// The compiler throws an error if an autosize property is assigned an unsupported value...
{
	const autosize = new Autosize();

	autosize.contains = 'abc'; // $ExpectError
	autosize.resize = '5'; // $ExpectError
	autosize.type = 'abc'; // $ExpectError
}

// An autosize instance has a read-only `properties` property...
{
	const autosize = new Autosize();

	const props = autosize.properties; // $ExpectType string[]
	if ( props.length !== 3 ) {
		throw new Error( 'unexpected error' );
	}
	autosize.properties = [ 'type' ]; // $ExpectError
}

// An autosize instance has a `toJSON` method which returns a JSON object...
{
	const autosize = new Autosize();

	autosize.toJSON(); // $ExpectType JSON
}

// The compiler throws an error if the `toJSON` method is provided arguments...
{
	const autosize = new Autosize();

	autosize.toJSON( {} ); // $ExpectError
}
